    # Define a function called display_price to display the price per pound based on the fruit selected by the user.    
    def display_price(self):
        # Get the fruit selected by the user and store it in the selected_fruit variable.
        selected_fruit = self.cmbFruit.currentText()
        # Get the price per pound of the fruit selected from the fruit_price dictionary.
