    # Define a function called calculate_cost that calculates the cost of the fruit purchase based on the quantity entered by the user.    
    def calculate_cost(self):
        # Get the quantity entered by the user and store it in the quantity variable and convert it to an integer.
        quantity = self.txtQuantity.text()
        
        # Validate the user entered the Quantity as a number.
        if(quantity.isdigit()):
        
            # Convert the quantity variable to an integer.
            quantity = int(quantity)
            # Get the fruit selected by the user and store it in the selected_fruit variable.
            selected_fruit = self.cmbFruit.currentText()
        
            if(selected_fruit in self.fruit_price.keys()):
                # Get the price of the fruit from the fruit_price dictionary.
                price_of_fruit = self.fruit_price.get(selected_fruit)
                # Calculate the cost of the fruit purchase and round it.
                cost_of_purchase = round(quantity*price_of_fruit, 2)
                # Display the cost of the fruit purchase in the text box.
                self.txtCost.setText(str(cost_of_purchase))
        
            # If user does not select a fruit, display a message box asking the user to select a fruit.
